package com.lucid.os.updater;

import android.app.Activity;import android.app.DownloadManager;import android.net.Uri;import android.os.Bundle;import android.os.Environment;import android.view.Gravity;import android.view.View;import android.widget.Button;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.TextView;import android.widget.Toast;import org.json.JSONObject;import java.io.BufferedInputStream;import java.io.File;import java.io.FileOutputStream;import java.net.HttpURLConnection;import java.net.URL;import java.security.MessageDigest;import java.util.Locale;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;

/** LucidOS updater UI. Checks a signed-official HTTPS manifest, downloads to app-private storage and verifies SHA-256. It never silently flashes or bypasses recovery security. */
public final class MainActivity extends Activity {
 private static final String MANIFEST_URL="https://raw.githubusercontent.com/NAANG360/Lucid-OS/main/ota/stable.json";
 private static final int BG=0xfff2f0f8,INK=0xff222237,MUTED=0xff666580,BLUE=0xff0866ff;private final ExecutorService io=Executors.newSingleThreadExecutor();private TextView status,version,details;private Button check,download;private JSONObject release;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);ScrollView sc=new ScrollView(this);sc.setBackgroundColor(BG);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(28),dp(24),dp(24));sc.addView(root);TextView brand=text("L U C I D",12,BLUE,true);root.addView(brand);TextView title=text("System Updater",32,INK,true);addTop(root,title,dp(8));TextView sub=text("Keep your LucidOS installation current.",15,MUTED,false);addTop(root,sub,dp(4));LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(18),dp(18),dp(18),dp(18));android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(-1);shape.setCornerRadius(dp(22));card.setBackground(shape);addTop(root,card,dp(24));version=text("Installed version: "+android.os.Build.DISPLAY,16,INK,true);card.addView(version);details=text("Device: "+android.os.Build.DEVICE+"\\nAndroid: "+android.os.Build.VERSION.RELEASE,13,MUTED,false);addTop(card,details,dp(10));status=text("Updates have not been checked.",14,INK,false);addTop(card,status,dp(16));check=new Button(this);check.setText("Check for updates");check.setOnClickListener(v->check());addTop(card,check,dp(12));download=new Button(this);download.setText("Download verified update");download.setEnabled(false);download.setOnClickListener(v->download());addTop(card,download,dp(8));TextView note=text("Packages are downloaded and hash-verified before use. Installing a full OTA still requires a compatible recovery or the platform update engine; this app will not pretend a download is an installation.",12,MUTED,false);addTop(root,note,dp(20));setContentView(sc);}
 private void check(){check.setEnabled(false);status.setText("Checking official update manifest…");io.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(MANIFEST_URL).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json");if(c.getResponseCode()!=200)throw new Exception("Manifest HTTP "+c.getResponseCode());byte[] bytes=c.getInputStream().readAllBytes();JSONObject m=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));if(!"lavender".equals(m.optString("device")))throw new Exception("Manifest device mismatch");String url=m.getString("url"),sha=m.getString("sha256");if(!url.startsWith("https://"))throw new Exception("Refusing non-HTTPS update URL");if(!sha.matches("(?i)[0-9a-f]{64}"))throw new Exception("Invalid SHA-256 in manifest");runOnUiThread(()->{release=m;status.setText("Update found: "+m.optString("version","version unspecified")+"\\n"+m.optString("changelog","No changelog supplied."));download.setEnabled(true);check.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{status.setText("Update check failed: "+e.getMessage());check.setEnabled(true);download.setEnabled(false);});}});}
 private void download(){if(release==null)return;download.setEnabled(false);status.setText("Downloading update…");io.execute(()->{File out=null;try{URL u=new URL(release.getString("url"));HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);if(c.getResponseCode()!=200)throw new Exception("Download HTTP "+c.getResponseCode());out=new File(getFilesDir(),"lucidos-update.zip");try(BufferedInputStream in=new BufferedInputStream(c.getInputStream());FileOutputStream os=new FileOutputStream(out)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)os.write(b,0,n);}String actual=sha256(out);if(!actual.equalsIgnoreCase(release.getString("sha256")))throw new Exception("SHA-256 mismatch; downloaded file deleted");File finalOut=out;runOnUiThread(()->{status.setText("Download verified (SHA-256). Saved privately: "+finalOut.getName()+". A compatible recovery/OTA installer is still required to install it.");download.setEnabled(true);Toast.makeText(this,"Update downloaded and verified",Toast.LENGTH_LONG).show();});}catch(Exception e){if(out!=null)out.delete();runOnUiThread(()->{status.setText("Download/verification failed: "+e.getMessage());download.setEnabled(true);});}});}
 private String sha256(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(java.io.InputStream in=new java.io.FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private TextView text(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(null,1);return t;}private void addTop(LinearLayout p,View v,int top){LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-1,-2);l.topMargin=top;p.addView(v,l);}private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+0.5f);}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
}
